const rows = $input.all();
const unused = rows.filter(item => { const used = String(item.json['Used'] ?? '').trim().toLowerCase(); return used === 'no' || used === ''; });
if (!unused.length) throw new Error('No unused experiences found in Experience Knowledge Base.');
const selected = unused[0].json;
return [{ json: { ...selected, selectedAt: new Date().toISOString(), selectionReason: 'First unused experience' } }];

